@st.cache_resource
def almacen_presencia():
    return {}, threading.Lock()


def registrar_presencia(sesion_id, usuario_id=None):
    sesiones, lock = almacen_presencia()
    identidad = ("cuenta", str(usuario_id)) if usuario_id else ("visita", sesion_id)
    with lock:
        ahora = time_module.monotonic()
        caducadas = [clave for clave, (_, ultima_signal) in sesiones.items()
                     if ahora - ultima_signal >= 45]
        for clave in caducadas:
            del sesiones[clave]
        sesiones[sesion_id] = (identidad, ahora)
        return len({identidad_activa for identidad_activa, _ in sesiones.values()})


@st.fragment(run_every="15s")
def mostrar_personas_en_linea(usuario_id=None):
    if "fb_presencia_id" not in st.session_state:
        st.session_state["fb_presencia_id"] = secrets.token_urlsafe(24)
    total = registrar_presencia(st.session_state["fb_presencia_id"], usuario_id)
    mensaje = "1 persona en línea" if total == 1 else f"{total} personas en línea"
    st.caption(f"🟢 {mensaje}")


def mostrar_pegatina_mural(entrada, mostrar_nombre=True, cuadrada=False):
    try:
        imagen_mural = base64.b64decode(entrada["imagen_webp"], validate=True)
        with Image.open(BytesIO(imagen_mural), formats=["WEBP"]) as imagen:
            if cuadrada:
                imagen.verify()
                contenido = base64.b64encode(imagen_mural).decode("ascii")
                nombre = escapar(str(entrada.get("nombre_grupo") or "Pegatina motera"))
                st.markdown(
                    '<div class="fb-pegatina-cuadrada">'
                    f'<img src="data:image/webp;base64,{contenido}" alt="{nombre}">'
                    '</div>',
                    unsafe_allow_html=True,
                )
            else:
                st.image(imagen.copy(), use_container_width=True)
    except (ValueError, OSError, Image.DecompressionBombError):
        if cuadrada:
            st.markdown(
                '<div class="fb-pegatina-cuadrada">Imagen no disponible</div>',
                unsafe_allow_html=True,
            )
        else:
            st.caption("Imagen no disponible.")
    if mostrar_nombre:
        st.text(entrada["nombre_grupo"])


def compartir_pegatina_mural(entrada):
    pegatina_id = str(entrada["id"])
    enlace_pegatina = FAMILYBIKE_PUBLIC_URL + "?" + urlencode({"pegatina": pegatina_id})
    mensaje = f"🏍️ Pegatina de {entrada['nombre_grupo']} en Family Bike\n{enlace_pegatina}"
    whatsapp, facebook = st.columns(2, gap="small")
    whatsapp.link_button(
        "WhatsApp", "https://wa.me/?" + urlencode({"text": mensaje}),
        use_container_width=True,
    )
    facebook.link_button(
        "Facebook", "https://www.facebook.com/sharer/sharer.php?" +
        urlencode({"u": enlace_pegatina}), use_container_width=True,
    )


def mostrar_mural_publico(pegatina_id):
    with st.container(key="fb_muro_portada"):
        st.markdown("## 🏍️ Muro de pegatinas")
        por_pagina = 6
        pagina = st.session_state.get("pagina_mural_publico", 0)
        if pegatina_id and st.button("← Ver todo el muro", key="mural_publico_ver_todo"):
            del st.query_params["pegatina"]
            st.session_state["pagina_mural_publico"] = 0
            st.rerun()

        try:
            entradas = supabase.rpc("familybike_mural_publico", {
                "id_buscado": pegatina_id,
                "desplazamiento": pagina * por_pagina,
            }).execute().data or []
        except Exception:
            st.caption("El muro de pegatinas no está disponible en este momento.")
            return

        if not entradas:
            if pegatina_id:
                st.info("Esta pegatina ya no está disponible.")
            elif pagina == 0:
                st.info("Todavía no hay pegatinas publicadas.")

        visibles = entradas[:por_pagina]
        if visibles:
            with st.container(key="fb_pegatinas_portada"):
                st.markdown(
                    """
                    <style>
                    .st-key-fb_pegatinas_portada [data-testid="stHorizontalBlock"] {
                        flex-wrap: nowrap;
                    }
                    .st-key-fb_pegatinas_portada [data-testid="stColumn"] {
                        flex: 1 1 0 !important;
                        min-width: 0 !important;
                        width: auto !important;
                    }
                    .fb-pegatina-cuadrada {
                        box-sizing: border-box;
                        width: 100%;
                        aspect-ratio: 1 / 1;
                        display: grid;
                        grid-template: minmax(0, 1fr) / minmax(0, 1fr);
                        place-items: center;
                        overflow: hidden;
                        padding: clamp(10px, 3vw, 24px);
                        border: 1px solid #454038;
                        border-radius: 14px;
                        background: radial-gradient(ellipse at center, #303238, #16171b);
                        color: #dedede;
                        text-align: center;
                    }
                    .fb-pegatina-cuadrada img {
                        display: block;
                        width: 100%;
                        height: 100%;
                        min-height: 0;
                        min-width: 0;
                        object-fit: contain;
                    }
                    .st-key-fb_pegatinas_portada [data-testid="stLinkButton"] a {
                        min-height: 0;
                        padding: .2rem .55rem;
                        font-size: .78rem;
                        line-height: 1.25;
                    }
                    </style>
                    """,
                    unsafe_allow_html=True,
                )
                for inicio in range(0, len(visibles), 2):
                    columnas = st.columns(2, gap="small")
                    for columna, entrada in zip(columnas, visibles[inicio:inicio + 2]):
                        with columna:
                            mostrar_pegatina_mural(
                                entrada, mostrar_nombre=False, cuadrada=True,
                            )
                            st.link_button(
                                "Me gusta",
                                iniciar_google_oauth(str(entrada["id"])),
                                key=f"mural_publico_votar_{entrada['id']}",
                            )

        if not pegatina_id and (pagina or len(entradas) > por_pagina):
            anterior, siguiente = st.columns(2)
            if anterior.button("← Anterior", disabled=pagina == 0, key="mural_publico_anterior"):
                st.session_state["pagina_mural_publico"] = pagina - 1
                st.rerun()
            if siguiente.button("Siguiente →", disabled=len(entradas) <= por_pagina,
                                key="mural_publico_siguiente"):
                st.session_state["pagina_mural_publico"] = pagina + 1
                st.rerun()



