if st.session_state["seccion_activa"] == "grupos":

    st.markdown(
        """
        <style>
        .stApp:has(#familybike-fondo-muro) [data-testid="stMain"] {
            --junta-ladrillo: #090a0b;
            background:
                linear-gradient(180deg, rgba(0, 0, 0, .08), rgba(0, 0, 0, .38)),
                repeating-linear-gradient(0deg, var(--junta-ladrillo) 0 3px, transparent 3px 45px),
                conic-gradient(
                    from 90deg at 3px 50%,
                    transparent 0 50%, var(--junta-ladrillo) 0 75%, transparent 0
                ) 0 0 / 144px 90px,
                conic-gradient(
                    from 90deg at 3px 50%,
                    transparent 0 25%, var(--junta-ladrillo) 0 50%, transparent 0
                ) 72px 0 / 144px 90px,
                repeating-linear-gradient(0deg, #1d1e20 0, #27282a 42px, #1d1e20 45px)
                #1d1e20 !important;
        }
        .stApp:has(#familybike-fondo-muro) [data-testid="stMainBlockContainer"] {
            background: transparent !important;
        }
        .stApp [data-testid="stElementContainer"]:has(#familybike-fondo-muro) {
            display: none;
        }
        </style>
        <span id="familybike-fondo-muro" aria-hidden="true"></span>
        """,
        unsafe_allow_html=True,
    )

    st.markdown("## 🏍️ Muro de pegatinas")
    st.caption("Comparte la pegatina de tu grupo en el muro de Family Bike.")

    pegatina_destacada = st.session_state.get("pegatina_compartida")
    tabla_mural = supabase.table("familybike_mural_pegatinas")
    por_pagina = 6
    pagina_mural = st.session_state.get("pagina_mural", 0)

    try:
        campos_mural = "id,nombre_grupo,imagen_webp"
        destacadas = []
        if pegatina_destacada:
            campos_destacada = campos_mural if pagina_mural == 0 else "id"
            destacadas = (
                tabla_mural.select(campos_destacada)
                .eq("id", pegatina_destacada).limit(1).execute().data or []
            )

        consulta_mural = tabla_mural.select(campos_mural).order("id", desc=True)
        if destacadas:
            consulta_mural = consulta_mural.neq("id", pegatina_destacada)
        inicio_mural = max(0, pagina_mural * por_pagina - len(destacadas))
        fijadas = destacadas if pagina_mural == 0 else []
        entradas_mural = fijadas + (
            consulta_mural.range(inicio_mural, inicio_mural + por_pagina - len(fijadas))
            .execute().data or []
        )
    except Exception:
        st.warning("El muro no está disponible en este momento.")
    else:
        if st.session_state.pop("mural_publicado", False):
            st.success("¡La pegatina de tu grupo ya está en el muro!")

        with st.expander("➕ Subir la pegatina de mi grupo"):
            with st.form("form_mural_pegatina"):
                nombre_grupo = st.text_input("Nombre del grupo", max_chars=70)
                pegatina = st.file_uploader(
                    "Imagen de la pegatina", type=["png", "jpg", "jpeg", "webp"],
                    help="Máximo 5 MB. El formato PNG conserva la transparencia.",
                )
                publicar = st.form_submit_button("Publicar pegatina", type="primary")

            if publicar:
                nombre_grupo = nombre_grupo.strip()
                if len(nombre_grupo) < 2 or pegatina is None:
                    st.warning("Escribe el nombre del grupo y selecciona una imagen.")
                else:
                    try:
                        imagen_webp = preparar_pegatina(pegatina)
                    except (OSError, ValueError, Image.DecompressionBombError) as error:
                        st.warning(str(error) if isinstance(error, ValueError)
                                   else "No se ha podido abrir la imagen. Prueba con otro archivo.")
                    else:
                        try:
                            tabla_mural.insert({
                                "usuario_id": str(usuario_id),
                                "nombre_grupo": nombre_grupo,
                                "imagen_webp": imagen_webp,
                            }).execute()
                        except Exception:
                            st.error("No se ha podido publicar la pegatina. Inténtalo de nuevo.")
                        else:
                            st.session_state["pagina_mural"] = 0
                            st.session_state.pop("pegatina_compartida", None)
                            st.session_state["mural_publicado"] = True
                            st.rerun()

        st.markdown("### Pegatinas publicadas")
        visibles = entradas_mural[:por_pagina]
        if pegatina_destacada and not destacadas:
            st.info("La pegatina seleccionada ya no está disponible.")
        if not visibles and pagina_mural == 0:
            st.info("El muro está vacío. ¡Anímate a subir la primera pegatina!")

        votos_mural = None
        if visibles:
            try:
                resumen = supabase.rpc("familybike_resumen_me_gusta_mural", {
                    "pegatinas": [{"id": entrada["id"]} for entrada in visibles],
                }).execute().data
                votos_mural = {fila["pegatina_id"]: fila for fila in resumen}
            except Exception:
                st.caption("Los Me gusta no están disponibles en este momento.")

        for inicio in range(0, len(visibles), 3):
            columnas = st.columns(3, gap="small")
            for columna, entrada in zip(columnas, visibles[inicio:inicio + 3]):
                with columna, st.container(border=True):
                    pegatina_id = str(entrada["id"])
                    if pegatina_id == pegatina_destacada:
                        st.caption("⭐ Pegatina seleccionada")
                    mostrar_pegatina_mural(entrada)
                    if votos_mural is not None:
                        voto = votos_mural.get(pegatina_id, {})
                        marcado = voto.get("mi_voto", False)
                        etiqueta = "❤️ Quitar Me gusta" if marcado else "🤍 Me gusta"
                        if st.button(
                            f"{etiqueta} · {voto.get('total', 0)}",
                            key=f"mural_me_gusta_{pegatina_id}",
                            use_container_width=True,
                        ):
                            tabla_votos = supabase.table("familybike_mural_me_gusta")
                            try:
                                if marcado:
                                    (tabla_votos.delete().eq("pegatina_id", pegatina_id)
                                     .eq("usuario_id", str(usuario_id)).execute())
                                else:
                                    tabla_votos.upsert(
                                        {"pegatina_id": pegatina_id, "usuario_id": str(usuario_id)},
                                        on_conflict="pegatina_id,usuario_id",
                                        ignore_duplicates=True,
                                    ).execute()
                            except Exception:
                                st.error("No se ha podido guardar tu Me gusta. Inténtalo de nuevo.")
                            else:
                                st.rerun()

                    compartir_pegatina_mural(entrada)

        if pagina_mural or len(entradas_mural) > por_pagina:
            anterior, siguiente = st.columns(2)
            if anterior.button("← Anterior", disabled=pagina_mural == 0, key="mural_anterior"):
                st.session_state["pagina_mural"] = pagina_mural - 1
                st.rerun()
            if siguiente.button("Siguiente →", disabled=len(entradas_mural) <= por_pagina, key="mural_siguiente"):
                st.session_state["pagina_mural"] = pagina_mural + 1
                st.rerun()


if st.session_state["seccion_activa"] == "colaboradores":
    st.markdown("## Colaboradores y empresas")

    try:
        ficha = (
            supabase.table("familybike_negocios")
            .select("nombre,actividad,descripcion,localidad,web,fotos")
            .eq("usuario_id", usuario_id)
            .limit(1)
            .execute()
        ).data
    except Exception:
        ficha = None
        st.warning("El directorio de negocios no está disponible en este momento.")

    if ficha is not None:
        negocio = ficha[0] if ficha else {}
        if st.session_state.pop("fb_negocio_publicado", False):
            st.success("Ficha publicada en Colaboradores y empresas.")
        revision = st.session_state.get("fb_revision_negocio", 0)
        with st.expander("Editar mi negocio" if negocio else "Añadir mi negocio"):
            with st.form(f"fb_negocio_form_{revision}"):
                nombre = st.text_input("Nombre del negocio", negocio.get("nombre", ""), max_chars=100)
                actividad = st.text_input("A qué se dedica", negocio.get("actividad", ""), max_chars=120)
                descripcion = st.text_area("Descripción", negocio.get("descripcion", ""), max_chars=1500)
                localidad = st.text_input("Localidad (opcional)", negocio.get("localidad", ""), max_chars=100)
                web = st.text_input("Web o red social (opcional)", negocio.get("web", ""), max_chars=250, placeholder="https://…")
                fotos_nuevas = st.file_uploader(
                    "Fotos o logotipo (hasta 3)", type=["jpg", "jpeg", "png", "webp"],
                    accept_multiple_files=True,
                )
                fotos_anteriores = negocio.get("fotos") or []
                if fotos_anteriores:
                    st.caption("Si subes fotos nuevas, sustituirán la galería actual.")
                quitar_fotos = bool(fotos_anteriores) and st.checkbox("Quitar las fotos actuales")
                guardar = st.form_submit_button("Publicar ficha" if not negocio else "Guardar cambios")

            if guardar:
                try:
                    if not nombre.strip() or not actividad.strip() or not descripcion.strip():
                        raise ValueError("Completa el nombre, la actividad y la descripción.")
                    web = web.strip()
                    if web:
                        enlace = urlparse(web)
                        if enlace.scheme != "https" or not enlace.hostname or enlace.username or enlace.password:
                            raise ValueError("Escribe una dirección web completa que empiece por https://.")
                    if len(fotos_nuevas) > 3:
                        raise ValueError("Puedes subir hasta tres fotos.")
                    fotos = fotos_anteriores
                    if fotos_nuevas:
                        try:
                            fotos = [preparar_pegatina(foto) for foto in fotos_nuevas]
                        except (OSError, Image.DecompressionBombError) as error:
                            raise ValueError("Una de las fotos no se puede leer o es demasiado grande.") from error
                    elif quitar_fotos:
                        fotos = []
                    supabase.table("familybike_negocios").upsert({
                        "usuario_id": usuario_id,
                        "nombre": nombre.strip(),
                        "actividad": actividad.strip(),
                        "descripcion": descripcion.strip(),
                        "localidad": localidad.strip(),
                        "web": web,
                        "fotos": fotos,
                    }, on_conflict="usuario_id").execute()
                    st.session_state["fb_revision_negocio"] = revision + 1
                    st.session_state["fb_negocio_publicado"] = True
                    st.session_state["fb_pagina_negocios"] = 0
                    st.rerun()
                except ValueError as error:
                    st.error(str(error))
                except Exception:
                    st.error("No se ha podido guardar la ficha. Inténtalo de nuevo.")

        pagina = st.session_state.get("fb_pagina_negocios", 0)
        por_pagina = 6
        inicio = pagina * por_pagina
        try:
            negocios = (
                supabase.table("familybike_negocios")
                .select("nombre,actividad,descripcion,localidad,web,fotos")
                .order("nombre").order("usuario_id")
                .range(inicio, inicio + por_pagina)
                .execute()
            ).data or []
        except Exception:
            st.warning("No se han podido cargar los negocios.")
        else:
            if not negocios:
                st.info("Todavía no hay negocios en esta página.")
            for empresa in negocios[:por_pagina]:
                with st.container(border=True):
                    st.text(empresa["nombre"])
                    st.text(" · ".join(filter(None, (empresa["actividad"], empresa["localidad"]))))
                    st.text(empresa["descripcion"])
                    fotos = empresa.get("fotos") or []
                    if fotos:
                        for columna, foto in zip(st.columns(len(fotos)), fotos):
                            with columna:
                                st.image("data:image/webp;base64," + foto, use_container_width=True)
                    if empresa["web"].startswith("https://"):
                        st.link_button("Visitar web", empresa["web"])
            if pagina or len(negocios) > por_pagina:
                anterior, siguiente = st.columns(2)
                if anterior.button("← Anterior", disabled=pagina == 0):
                    st.session_state["fb_pagina_negocios"] = pagina - 1
                    st.rerun()
                if siguiente.button("Siguiente →", disabled=len(negocios) <= por_pagina):
                    st.session_state["fb_pagina_negocios"] = pagina + 1
                    st.rerun()


# =========================================================
